CREATE TABLE IF NOT EXISTS case_details(demand_id TEXT PRIMARY KEY REFERENCES demands(id),payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_files(id TEXT PRIMARY KEY,demand_id TEXT NOT NULL REFERENCES demands(id),kind TEXT NOT NULL,name TEXT NOT NULL,mime TEXT NOT NULL,bytes BLOB NOT NULL,uploaded_by TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,verified_by TEXT REFERENCES users(id),verified_at TEXT);
CREATE TABLE IF NOT EXISTS signed_history(id TEXT PRIMARY KEY,matrix_id TEXT NOT NULL REFERENCES contracts(id),sequence INTEGER NOT NULL CHECK(sequence>=0),source TEXT NOT NULL,reference TEXT NOT NULL,signature_date TEXT NOT NULL,confirmed_by TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,UNIQUE(matrix_id,sequence));
CREATE TABLE IF NOT EXISTS history_confirmations(id TEXT PRIMARY KEY,matrix_id TEXT NOT NULL REFERENCES contracts(id),sequence INTEGER NOT NULL,source TEXT NOT NULL CHECK(source IN('Clicksign','Clint')),reference TEXT NOT NULL,signature_date TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,UNIQUE(matrix_id,sequence,source,reference));
CREATE TABLE IF NOT EXISTS template_catalog(version_id TEXT PRIMARY KEY REFERENCES template_versions(id),document_type TEXT NOT NULL,subtype TEXT NOT NULL DEFAULT '',demonstration INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS human_checks(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),data_version INTEGER NOT NULL,axis TEXT NOT NULL,result TEXT NOT NULL,notes TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS human_issues(id TEXT PRIMARY KEY,check_id TEXT NOT NULL REFERENCES human_checks(id),location TEXT NOT NULL,problem TEXT NOT NULL,correction TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN('menor','crítica')));
CREATE TABLE IF NOT EXISTS signature_records(document_id TEXT PRIMARY KEY REFERENCES documents(id),mime TEXT NOT NULL,name TEXT NOT NULL,user_id TEXT NOT NULL REFERENCES users(id),created TEXT NOT NULL,attested INTEGER NOT NULL CHECK(attested=1));
CREATE TRIGGER IF NOT EXISTS immutable_signed_history BEFORE UPDATE ON signed_history BEGIN SELECT RAISE(ABORT,'Histórico confirmado é imutável'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_signed_history BEFORE DELETE ON signed_history BEGIN SELECT RAISE(ABORT,'Histórico confirmado é imutável'); END;
CREATE TRIGGER IF NOT EXISTS immutable_history_confirmation BEFORE UPDATE ON history_confirmations BEGIN SELECT RAISE(ABORT,'Confirmação externa é imutável'); END;
CREATE TRIGGER IF NOT EXISTS no_delete_history_confirmation BEFORE DELETE ON history_confirmations BEGIN SELECT RAISE(ABORT,'Confirmação externa é imutável'); END;
UPDATE approvals SET valid=0 WHERE NOT EXISTS(SELECT 1 FROM settings WHERE key='governanceVersion') AND document_id IN(SELECT doc.id FROM documents doc JOIN demands d ON d.id=doc.demand_id WHERE d.stage NOT IN('Concluído','Cancelado'));
UPDATE demands SET confirmed=0 WHERE NOT EXISTS(SELECT 1 FROM settings WHERE key='governanceVersion') AND stage NOT IN('Concluído','Cancelado');
INSERT OR IGNORE INTO settings VALUES('governanceVersion','2');
